import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
const sha = b => createHash('sha256').update(b).digest('hex');
const HERE=path.dirname(fileURLToPath(import.meta.url));
const W=path.resolve(HERE,'../../../');
const base=path.join(W,'challenge-host-tls-20261021/tree');
const candidate=path.resolve(HERE,'../hs2-tree');
const esbuild=createRequire(path.join(base,'package.json'))('esbuild');
async function bundle(TREE, esbuild, entry, outfile, { ownEntryCheck }) {
  const r = await esbuild.build({ absWorkingDir: TREE, entryPoints: [entry], outfile, write: false, metafile: true, bundle: true, platform: 'node', format: 'esm',
    target: 'node22', legalComments: 'none',
    banner: { js: `// Generated by work/hosted-services-activation/build-stage-r2.mjs from ${entry}; do not edit.\nimport {createRequire as __enclaveStageCreateRequire} from "node:module"; const require=__enclaveStageCreateRequire(import.meta.url);` } });
  const bytes = Buffer.from(r.outputFiles[0].contents);
  const probe = path.join(os.tmpdir(), `stage-probe-${process.pid}-${path.basename(outfile)}`);
  try { fs.writeFileSync(probe, bytes); execFileSync(process.execPath, ['--check', probe], { stdio: ['ignore', 'ignore', 'pipe'] }); }
  catch (e) { throw new Error(`${entry}: the bundle does not parse: ${String(e.stderr || e.message).slice(0, 400)}`); }
  finally { fs.rmSync(probe, { force: true }); }
  const checks = (bytes.toString('utf8').match(/process\.argv\[1\]\s*&&[^\n]{0,200}import\.meta\.url/g) || []).length;
  if (ownEntryCheck && checks !== 1) throw new Error(`${entry}: ${checks} "main module" checks in the bundle; exactly its own is allowed`);
  const inputs = {};
  for (const rel of Object.keys(r.metafile.inputs).sort()) {
    const norm = rel.includes('node_modules/') ? 'node_modules/' + rel.split('node_modules/').pop() : rel;
    inputs[norm] = sha(fs.readFileSync(path.resolve(TREE, rel)));
  }
  return { bytes, inputs };
}

const live=JSON.parse(fs.readFileSync(path.join(W,'challenge-host-tls-20261021/g4/upgrade-bundle-g4/upgrade-manifest.json')));
const originalInputs=JSON.parse(fs.readFileSync(path.join(W,'challenge-host-tls-20261021/g4/stage-g4/stage-r2/enclave-host-services-hs2-windows/STAGE-INPUTS.json')));
const report={};
for (const [entry,file,ownEntryCheck,closure] of [
 ['network/host-services/runner.mjs','host-services-runner.mjs',true,'runnerClosure'],
 ['network/host-services/entries/stage-tool.mjs','stage-tool.mjs',false,'toolClosure']
]) {
 const old=await bundle(base,esbuild,entry,file,{ownEntryCheck});
 const expected=live.replace.find(x=>x.path==='bin/'+file).new;
 fs.mkdirSync(path.join(HERE,'baseline'),{recursive:true}); fs.writeFileSync(path.join(HERE,'baseline',file),old.bytes);
 assert.equal(sha(old.bytes),expected,`baseline must reproduce the live ${file}`);
 assert.deepEqual(old.inputs,originalInputs[closure],`baseline input inventory ${file}`);
 const next=await bundle(candidate,esbuild,entry,file,{ownEntryCheck});
 const diff=[...new Set([...Object.keys(old.inputs),...Object.keys(next.inputs)])].filter(k=>old.inputs[k]!==next.inputs[k]);
 assert.deepEqual(diff,['network/host-services/roles.mjs'],`only the reviewed role validator may differ: ${file}`);
 fs.mkdirSync(path.join(HERE,'artifacts'),{recursive:true});fs.writeFileSync(path.join(HERE,'artifacts',file),next.bytes);
 fs.writeFileSync(path.join(HERE,'artifacts',file+'.inputs.json'),JSON.stringify(next.inputs,null,2)+'\n');
 report[file]={baselineSha256:expected,candidateSha256:sha(next.bytes),bytes:next.bytes.length,inputCount:Object.keys(next.inputs).length,changedInputs:diff};
 console.log(JSON.stringify({file,...report[file]}));
}
fs.writeFileSync(path.join(HERE,'build-result.json'),JSON.stringify(report,null,2)+'\n');
